target.css:
:root {
  --ink: #20232b;
  --paper: #fffdf7;
  --coral: #f06b52;
  --mint: #ccefe1;
  --line: #d9d3c7;
}

.photo-ticket {
  width: 440px;
  overflow: hidden;
  color: var(--ink);
  background: var(--paper);
  border: 1px solid var(--line);
  border-radius: 16px;
}

.ticket-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 10px 16px;
  background: var(--mint);
}

.venue,
.serial,
.ticket-footer {
  margin: 0;
  font-size: 12px;
  font-weight: 700;
  letter-spacing: 0.08em;
}

.ticket-main {
  display: flex;
  align-items: center;
  gap: 14px;
  padding: 18px 16px;
}

.camera-mark {
  display: grid;
  width: 52px;
  height: 52px;
  margin: 0;
  place-items: center;
  font-size: 28px;
  background: var(--coral);
  border-radius: 12px;
}

.session-copy h1 {
  margin: 0 0 3px;
  font-size: 22px;
  line-height: 1;
}

.session-copy p {
  margin: 0;
  font-size: 14px;
}

.ticket-footer {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 10px 16px;
  border-top: 1px dashed var(--line);
}

.ticket-footer button {
  padding: 7px 11px;
  color: var(--paper);
  font: inherit;
  font-size: 12px;
  font-weight: 700;
  background: var(--ink);
  border: 0;
  border-radius: 7px;
}
